import{_ as n,I as s,o as h,c as l,b6 as a,J as i}from"./chunks/framework.COUcLbTA.js";const y=JSON.parse('{"title":"一个请求的完整旅程","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/appendix/4-server-and-backend/request-journey.md","filePath":"zh-cn/appendix/4-server-and-backend/request-journey.md"}'),r={name:"zh-cn/appendix/4-server-and-backend/request-journey.md"};function p(o,t,k,c,b,g){const e=s("RequestJourneyFlow"),d=s("RequestTimeline");return h(),l("div",null,[t[0]||(t[0]=a('<h1 id="一个请求的完整旅程" tabindex="-1">一个请求的完整旅程 <a class="header-anchor" href="#一个请求的完整旅程" aria-label="Permalink to “一个请求的完整旅程”">​</a></h1><div class="tip custom-block"><p class="custom-block-title">前言</p><p><strong>当你在浏览器里输入一个网址按下回车，到页面显示出来，中间到底发生了什么？</strong> 这个问题是面试经典题，更是理解整个 Web 架构的钥匙。搞懂这条链路，你就能理解前端、后端、网络、数据库是怎么协作的。</p></div><p><strong>这篇文章会带你学什么？</strong></p><p>学完这章后，你将获得：</p><ul><li><strong>全链路视角</strong>：理解一个 HTTP 请求从发出到返回的完整过程</li><li><strong>各层职责认知</strong>：DNS、TCP、负载均衡、Web 服务器、应用服务器、数据库各自做什么</li><li><strong>问题定位能力</strong>：请求慢或失败时，知道从哪一层开始排查</li><li><strong>性能优化思路</strong>：每一层都有优化空间，知道优化点在哪里</li></ul><table tabindex="0"><thead><tr><th>章节</th><th>内容</th><th>核心概念</th></tr></thead><tbody><tr><td><strong>第 1 章</strong></td><td>浏览器发起请求</td><td>DNS 解析、TCP 连接、HTTP 请求</td></tr><tr><td><strong>第 2 章</strong></td><td>网络传输</td><td>路由、CDN、负载均衡</td></tr><tr><td><strong>第 3 章</strong></td><td>服务器处理</td><td>Web 服务器、应用逻辑、数据库查询</td></tr><tr><td><strong>第 4 章</strong></td><td>响应返回</td><td>序列化、压缩、渲染</td></tr><tr><td><strong>第 5 章</strong></td><td>全链路优化</td><td>缓存、连接复用、异步处理</td></tr></tbody></table><hr><h2 id="_0-全景图-一个请求经历了什么" tabindex="-1">0. 全景图：一个请求经历了什么？ <a class="header-anchor" href="#_0-全景图-一个请求经历了什么" aria-label="Permalink to “0. 全景图：一个请求经历了什么？”">​</a></h2><p>用一个比喻来理解：你在网上下单买书，这个过程和 HTTP 请求惊人地相似。</p><table tabindex="0"><thead><tr><th>请求阶段</th><th>买书类比</th><th>技术对应</th></tr></thead><tbody><tr><td>输入网址</td><td>你说&quot;我要去某某书店&quot;</td><td>浏览器解析 URL</td></tr><tr><td>DNS 解析</td><td>查地图找到书店地址</td><td>域名 → IP 地址</td></tr><tr><td>TCP 连接</td><td>走到书店门口，推门进去</td><td>三次握手建立连接</td></tr><tr><td>发送请求</td><td>告诉店员&quot;我要《xxx》这本书&quot;</td><td>HTTP 请求报文</td></tr><tr><td>服务器处理</td><td>店员去仓库找书、查库存、算价格</td><td>应用逻辑 + 数据库查询</td></tr><tr><td>返回响应</td><td>店员把书递给你</td><td>HTTP 响应报文</td></tr><tr><td>浏览器渲染</td><td>你打开书开始阅读</td><td>HTML/CSS/JS 解析渲染</td></tr></tbody></table>',10)),i(e),t[1]||(t[1]=a(`<hr><h2 id="_1-浏览器发起请求" tabindex="-1">1. 浏览器发起请求 <a class="header-anchor" href="#_1-浏览器发起请求" aria-label="Permalink to “1. 浏览器发起请求”">​</a></h2><h3 id="_1-1-url-解析" tabindex="-1">1.1 URL 解析 <a class="header-anchor" href="#_1-1-url-解析" aria-label="Permalink to “1.1 URL 解析”">​</a></h3><p>当你输入 <code>https://api.example.com/books?id=123</code> 时，浏览器会把它拆解成几个部分：</p><table tabindex="0"><thead><tr><th>部分</th><th>值</th><th>含义</th></tr></thead><tbody><tr><td>协议</td><td><code>https</code></td><td>用加密方式通信</td></tr><tr><td>域名</td><td><code>api.example.com</code></td><td>服务器的&quot;名字&quot;</td></tr><tr><td>路径</td><td><code>/books</code></td><td>要访问的资源</td></tr><tr><td>查询参数</td><td><code>id=123</code></td><td>附加条件</td></tr></tbody></table><h3 id="_1-2-dns-解析-域名-→-ip-地址" tabindex="-1">1.2 DNS 解析：域名 → IP 地址 <a class="header-anchor" href="#_1-2-dns-解析-域名-→-ip-地址" aria-label="Permalink to “1.2 DNS 解析：域名 → IP 地址”">​</a></h3><p>计算机不认识域名，只认识 IP 地址（如 <code>93.184.216.34</code>）。DNS 就是互联网的&quot;电话簿&quot;。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>浏览器缓存 → 系统缓存 → 路由器缓存 → ISP DNS → 根域名服务器</span></span>
<span class="line"><span>     ↓ 命中就直接用，不命中就往下查</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">DNS 缓存的意义</p><p>如果每次请求都从根域名服务器查起，全球互联网会被 DNS 查询压垮。所以每一层都有缓存，大部分请求在浏览器或系统层就能解析完成。</p></div><h3 id="_1-3-tcp-三次握手" tabindex="-1">1.3 TCP 三次握手 <a class="header-anchor" href="#_1-3-tcp-三次握手" aria-label="Permalink to “1.3 TCP 三次握手”">​</a></h3><p>找到 IP 地址后，浏览器需要和服务器&quot;建立连接&quot;。TCP 用三次握手确保双方都准备好了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>客户端 → 服务器：你好，我想连接（SYN）</span></span>
<span class="line"><span>服务器 → 客户端：好的，我准备好了（SYN + ACK）</span></span>
<span class="line"><span>客户端 → 服务器：收到，开始通信（ACK）</span></span></code></pre></div><p>如果是 HTTPS，还需要额外的 TLS 握手来协商加密方式。</p><h3 id="_1-4-发送-http-请求" tabindex="-1">1.4 发送 HTTP 请求 <a class="header-anchor" href="#_1-4-发送-http-请求" aria-label="Permalink to “1.4 发送 HTTP 请求”">​</a></h3><p>连接建立后，浏览器发送 HTTP 请求报文：</p><div class="language-http"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /books?id=123 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Accept</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer eyJhbGci...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">User-Agent</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Chrome/120.0</span></span></code></pre></div><table tabindex="0"><thead><tr><th>组成部分</th><th>内容</th></tr></thead><tbody><tr><td>请求行</td><td>方法（GET）+ 路径 + 协议版本</td></tr><tr><td>请求头</td><td>元信息：身份认证、期望的数据格式等</td></tr><tr><td>请求体</td><td>POST/PUT 请求才有，携带要提交的数据</td></tr></tbody></table><hr><h2 id="_2-网络传输-请求在路上" tabindex="-1">2. 网络传输：请求在路上 <a class="header-anchor" href="#_2-网络传输-请求在路上" aria-label="Permalink to “2. 网络传输：请求在路上”">​</a></h2><h3 id="_2-1-路由转发" tabindex="-1">2.1 路由转发 <a class="header-anchor" href="#_2-1-路由转发" aria-label="Permalink to “2.1 路由转发”">​</a></h3><p>请求离开你的电脑后，会经过多个路由器的转发，就像快递经过多个中转站：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>你的电脑 → 家庭路由器 → 运营商网络 → 骨干网 → 目标机房</span></span></code></pre></div><p>每个路由器根据 IP 地址决定&quot;下一跳&quot;往哪里转发。可以用 <code>traceroute</code> 命令查看请求经过了哪些节点。</p><h3 id="_2-2-cdn-加速" tabindex="-1">2.2 CDN 加速 <a class="header-anchor" href="#_2-2-cdn-加速" aria-label="Permalink to “2.2 CDN 加速”">​</a></h3><p>如果目标网站使用了 CDN（内容分发网络），请求可能不需要到达源服务器：</p><table tabindex="0"><thead><tr><th>场景</th><th>走向</th></tr></thead><tbody><tr><td>请求静态资源（图片、CSS、JS）</td><td>CDN 边缘节点直接返回</td></tr><tr><td>请求动态数据（API）</td><td>穿透 CDN，到达源服务器</td></tr></tbody></table><p>CDN 的本质是&quot;把内容提前放到离用户最近的地方&quot;。</p><h3 id="_2-3-负载均衡" tabindex="-1">2.3 负载均衡 <a class="header-anchor" href="#_2-3-负载均衡" aria-label="Permalink to “2.3 负载均衡”">​</a></h3><p>大型网站不会只有一台服务器。负载均衡器负责把请求分配到多台服务器上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>用户请求 → 负载均衡器 → 服务器 A（30% 流量）</span></span>
<span class="line"><span>                      → 服务器 B（30% 流量）</span></span>
<span class="line"><span>                      → 服务器 C（40% 流量）</span></span></code></pre></div><p>常见的分配策略：</p><table tabindex="0"><thead><tr><th>策略</th><th>原理</th><th>适用场景</th></tr></thead><tbody><tr><td>轮询</td><td>依次分配</td><td>服务器配置相同</td></tr><tr><td>加权轮询</td><td>按权重分配</td><td>服务器配置不同</td></tr><tr><td>IP 哈希</td><td>同一用户固定到同一台</td><td>需要会话保持</td></tr><tr><td>最少连接</td><td>分给当前连接最少的</td><td>请求处理时间差异大</td></tr></tbody></table><hr><h2 id="_3-服务器处理-厨房里发生了什么" tabindex="-1">3. 服务器处理：厨房里发生了什么 <a class="header-anchor" href="#_3-服务器处理-厨房里发生了什么" aria-label="Permalink to “3. 服务器处理：厨房里发生了什么”">​</a></h2><p>请求到达服务器后，会经过多层处理。</p><h3 id="_3-1-web-服务器-nginx-apache" tabindex="-1">3.1 Web 服务器（Nginx / Apache） <a class="header-anchor" href="#_3-1-web-服务器-nginx-apache" aria-label="Permalink to “3.1 Web 服务器（Nginx / Apache）”">​</a></h3><p>第一个接收请求的通常是 Web 服务器，它负责：</p><table tabindex="0"><thead><tr><th>职责</th><th>说明</th></tr></thead><tbody><tr><td>静态文件服务</td><td>直接返回 HTML、CSS、JS、图片</td></tr><tr><td>反向代理</td><td>把 API 请求转发给后端应用</td></tr><tr><td>SSL 终止</td><td>处理 HTTPS 加密解密</td></tr><tr><td>请求过滤</td><td>拦截恶意请求、限流</td></tr></tbody></table><h3 id="_3-2-应用服务器处理" tabindex="-1">3.2 应用服务器处理 <a class="header-anchor" href="#_3-2-应用服务器处理" aria-label="Permalink to “3.2 应用服务器处理”">​</a></h3><p>Web 服务器把请求转发给应用服务器（Node.js、Spring、Django 等），处理流程：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请求进入 → 中间件链 → 路由匹配 → 控制器 → 服务层 → 数据访问层</span></span></code></pre></div><p><strong>中间件</strong>做的事情：</p><ol><li>解析请求体（JSON、表单数据）</li><li>验证身份（检查 Token）</li><li>检查权限（这个用户能访问这个接口吗？）</li><li>记录日志（谁在什么时候访问了什么）</li></ol><h3 id="_3-3-数据库查询" tabindex="-1">3.3 数据库查询 <a class="header-anchor" href="#_3-3-数据库查询" aria-label="Permalink to “3.3 数据库查询”">​</a></h3><p>大部分请求最终都要和数据库打交道：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>应用代码：SELECT * FROM books WHERE id = 123</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>数据库引擎：解析 SQL → 查询优化 → 执行计划 → 读取数据</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>返回结果：{ id: 123, title: &quot;xxx&quot;, price: 59.9 }</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">数据库是最常见的性能瓶颈</p><p>网络传输通常是毫秒级，应用逻辑也很快，但一个没有索引的数据库查询可能要几秒甚至几十秒。所以&quot;慢请求&quot;大概率是数据库查询慢。</p></div><hr><h2 id="_4-响应返回-数据的归途" tabindex="-1">4. 响应返回：数据的归途 <a class="header-anchor" href="#_4-响应返回-数据的归途" aria-label="Permalink to “4. 响应返回：数据的归途”">​</a></h2><h3 id="_4-1-构造-http-响应" tabindex="-1">4.1 构造 HTTP 响应 <a class="header-anchor" href="#_4-1-构造-http-响应" aria-label="Permalink to “4.1 构造 HTTP 响应”">​</a></h3><p>服务器处理完后，构造响应报文：</p><div class="language-http"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OK</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Encoding</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gzip</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Cache-Control</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> max-age=3600</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xxx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;price&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">59.9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>组成部分</th><th>内容</th></tr></thead><tbody><tr><td>状态行</td><td>协议版本 + 状态码（200 成功、404 未找到、500 服务器错误）</td></tr><tr><td>响应头</td><td>数据格式、缓存策略、压缩方式等</td></tr><tr><td>响应体</td><td>实际的数据内容（JSON、HTML 等）</td></tr></tbody></table><h3 id="_4-2-数据压缩" tabindex="-1">4.2 数据压缩 <a class="header-anchor" href="#_4-2-数据压缩" aria-label="Permalink to “4.2 数据压缩”">​</a></h3><p>服务器通常会用 gzip 或 brotli 压缩响应体，减少传输量：</p><table tabindex="0"><thead><tr><th>压缩算法</th><th>压缩率</th><th>速度</th></tr></thead><tbody><tr><td>gzip</td><td>约 70%</td><td>快</td></tr><tr><td>brotli</td><td>约 80%</td><td>较慢但压缩更好</td></tr></tbody></table><p>一个 100KB 的 JSON，压缩后可能只有 20-30KB。</p><h3 id="_4-3-浏览器渲染" tabindex="-1">4.3 浏览器渲染 <a class="header-anchor" href="#_4-3-浏览器渲染" aria-label="Permalink to “4.3 浏览器渲染”">​</a></h3><p>浏览器收到响应后：</p><ol><li><strong>解析 HTML</strong> → 构建 DOM 树</li><li><strong>解析 CSS</strong> → 构建样式树</li><li><strong>合并</strong> → 生成渲染树</li><li><strong>布局</strong> → 计算每个元素的位置和大小</li><li><strong>绘制</strong> → 把像素画到屏幕上</li></ol>`,60)),i(d),t[2]||(t[2]=a('<hr><h2 id="_5-全链路优化-每一层都能更快" tabindex="-1">5. 全链路优化：每一层都能更快 <a class="header-anchor" href="#_5-全链路优化-每一层都能更快" aria-label="Permalink to “5. 全链路优化：每一层都能更快”">​</a></h2><h3 id="_5-1-各层优化手段" tabindex="-1">5.1 各层优化手段 <a class="header-anchor" href="#_5-1-各层优化手段" aria-label="Permalink to “5.1 各层优化手段”">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>优化手段</th><th>效果</th></tr></thead><tbody><tr><td>DNS</td><td>DNS 预解析、使用快速 DNS 服务</td><td>减少 DNS 查询时间</td></tr><tr><td>网络</td><td>CDN、HTTP/2、连接复用</td><td>减少传输延迟</td></tr><tr><td>服务器</td><td>缓存（Redis）、异步处理</td><td>减少处理时间</td></tr><tr><td>数据库</td><td>索引、查询优化、读写分离</td><td>减少查询时间</td></tr><tr><td>前端</td><td>懒加载、代码分割、资源压缩</td><td>减少渲染时间</td></tr></tbody></table><h3 id="_5-2-缓存-最有效的优化" tabindex="-1">5.2 缓存：最有效的优化 <a class="header-anchor" href="#_5-2-缓存-最有效的优化" aria-label="Permalink to “5.2 缓存：最有效的优化”">​</a></h3><p>缓存存在于请求链路的每一层：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>浏览器缓存 → CDN 缓存 → 反向代理缓存 → 应用缓存（Redis）→ 数据库缓存</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">缓存的本质</p><p>用空间换时间。把计算过的结果存起来，下次直接用，不用重新算。缓存命中率每提高 10%，系统性能可能提升数倍。</p></div><h3 id="_5-3-请求失败时的排查思路" tabindex="-1">5.3 请求失败时的排查思路 <a class="header-anchor" href="#_5-3-请求失败时的排查思路" aria-label="Permalink to “5.3 请求失败时的排查思路”">​</a></h3><table tabindex="0"><thead><tr><th>现象</th><th>可能的问题层</th><th>排查方法</th></tr></thead><tbody><tr><td>完全无响应</td><td>DNS / 网络</td><td>ping、nslookup</td></tr><tr><td>连接超时</td><td>网络 / 服务器宕机</td><td>telnet、curl</td></tr><tr><td>返回 4xx</td><td>客户端请求有误</td><td>检查 URL、参数、Token</td></tr><tr><td>返回 5xx</td><td>服务器内部错误</td><td>查看服务器日志</td></tr><tr><td>响应很慢</td><td>数据库 / 应用逻辑</td><td>查看慢查询日志、APM 工具</td></tr></tbody></table><hr><h2 id="_6-总结" tabindex="-1">6. 总结 <a class="header-anchor" href="#_6-总结" aria-label="Permalink to “6. 总结”">​</a></h2><p>一个 HTTP 请求的完整旅程：</p><ol><li><strong>浏览器</strong>：解析 URL → DNS 查询 → TCP 连接 → 发送请求</li><li><strong>网络</strong>：路由转发 → CDN 判断 → 负载均衡分发</li><li><strong>服务器</strong>：Web 服务器接收 → 中间件处理 → 业务逻辑 → 数据库查询</li><li><strong>返回</strong>：构造响应 → 压缩 → 网络传输 → 浏览器渲染</li></ol><div class="tip custom-block"><p class="custom-block-title">理解全链路的价值</p><p>当你能在脑中画出请求的完整链路时，遇到任何问题都能快速定位到是哪一层出了问题。这是从&quot;初级开发&quot;到&quot;能独立排查问题&quot;的关键跨越。</p></div><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to “延伸阅读”">​</a></h2><ul><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/HTTP" target="_blank" rel="noreferrer">HTTP 权威指南</a> — MDN 的 HTTP 文档</li><li><a href="https://hpbn.co/" target="_blank" rel="noreferrer">High Performance Browser Networking</a> — 浏览器网络性能优化</li><li><a href="https://github.com/alex/what-happens-when" target="_blank" rel="noreferrer">What happens when...</a> — 经典的&quot;输入 URL 后发生了什么&quot;详解</li></ul>',18))])}const _=n(r,[["render",p]]);export{y as __pageData,_ as default};
